#!/usr/bin/env node
// Bundles bank/*.json into app/bank.js so index.html can load the bank from file://
// (browsers block fetch() of local files). Run after editing the bank and check_bank.js:
//   node tools/bundle_bank.js
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const bankDir = path.join(root, 'bank');
const out = path.join(root, 'app', 'bank.js');

const parts = {
  meta: 'meta.json',
  questions: 'questions.json',
  decisions: 'decisions.json',
  steps: 'steps.json',
  features: 'features.json',
  sources: 'sources.json',
  loadOrder: 'loadOrder.json',
  oneWayDoors: 'oneWayDoors.json',
  moduleScoping: 'moduleScoping.json',
  prework: 'prework.json',
  systemsTables: 'systemsTables.json',
  fileChecklist: 'fileChecklist.json',
};

const bank = {};
for (const [key, file] of Object.entries(parts)) {
  bank[key] = JSON.parse(fs.readFileSync(path.join(bankDir, file), 'utf8'));
}

const body = '// GENERATED by tools/bundle_bank.js from bank/*.json - do not edit.\n'
  + 'window.BANK = ' + JSON.stringify(bank) + ';\n';
fs.writeFileSync(out, body);
console.log('wrote ' + path.relative(root, out) + ' (' + body.length + ' bytes)');
